import React, { useState, useRef } from 'react';
import type { FormInstance } from '@cloud-materials/common';
import { CEllipsis, Form, Input, Typography, Radio, InputNumber, Button } from '@cloud-materials/common';

import type { CEllipsisProps } from '../interface';

const defaultValues = {
  maxWidth: 200,
  children: '正是江南好时节，落花时节又逢君',
};

const onClick = () => {
  console.log('click');
};

export default () => {
  const formRef = useRef<FormInstance>(null);
  const [config, setConfig] = useState<CEllipsisProps>(defaultValues);

  const renderPopoverContent = (isTextOverflow: boolean, content: string) => {
    return `当前渲染文本${isTextOverflow ? '溢出' : '未溢出'}, ${content}`;
  };

  return (
    <>
      <Typography.Title heading={4}>在线配置 Ellipsis Props</Typography.Title>
      <Form
        style={{ maxWidth: 800 }}
        ref={formRef}
        labelCol={{ span: 5 }}
        initialValues={config}
        onValuesChange={(_, values: CEllipsisProps) => {
          setConfig(values);
        }}
      >
        <Form.Item label="文本值" field="children" rules={[{ required: true }]}>
          <Input />
        </Form.Item>
        <Form.Item label="最大宽度" field="maxWidth">
          <InputNumber placeholder="控制 Ellipsis 组件可渲染的最大宽度" />
        </Form.Item>
        <Form.Item label="Popover 组件渲染" field="showPopover">
          <Radio.Group type="button">
            <Radio value={true}>固定渲染</Radio>
            <Radio value="auto">根据文本宽度，自动计算进行渲染</Radio>
            <Radio value={false}>不渲染</Radio>
          </Radio.Group>
        </Form.Item>
        <Form.Item label="Copy 组件渲染" field="showCopy">
          <Radio.Group type="button">
            <Radio value={true}>固定渲染</Radio>
            <Radio value="hover">Hover 渲染</Radio>
            <Radio value={false}>隐藏</Radio>
          </Radio.Group>
        </Form.Item>
        <Form.Item label="Copy 组件渲染位置" field="copyPosition">
          <Radio.Group type="button">
            <Radio value="Container">文本信息后</Radio>
            <Radio value="Popover">Popover 内</Radio>
          </Radio.Group>
        </Form.Item>
        <Form.Item label="Suffix" field="suffix">
          <Input placeholder="填写一些额外操作提示内容" />
        </Form.Item>
        <Form.Item>
          <Button
            onClick={() => {
              formRef.current!.resetFields();
            }}
          >
            Reset
          </Button>
        </Form.Item>
      </Form>
      <Input.TextArea style={{ width: 500 }} disabled autoSize value={JSON.stringify(config)} />
      <Typography.Title heading={4}>Ellipsis 实时渲染</Typography.Title>
      <CEllipsis popoverContent={renderPopoverContent} onClick={onClick} {...config} />
    </>
  );
};

import { useCEllipsis, Typography, Space, Radio, Slider } from '@cloud-materials/common';
import React, { useState, useRef } from 'react';

const style = {
  textOverflow: 'ellipsis',
  whiteSpace: 'nowrap' as const,
  overflow: 'hidden',
};

export default function Demo() {
  const [width, setWidth] = useState(150);
  const targetRef = useRef<HTMLParagraphElement>(null);
  const [{ isTextOverflow }] = useCEllipsis(targetRef);

  return (
    <Space direction="vertical">
      <Typography.Title heading={4}>基于 useCEllipsis, 实现 UI 定制</Typography.Title>
      <Space size="medium">
        <span>文本容器宽度调整：</span>
        <Slider
          value={width}
          onChange={value => setWidth(value as number)}
          min={100}
          max={300}
          marks={{
            100: '100px',
            300: '300px',
          }}
          style={{ width: 200 }}
        />
      </Space>
      <p style={{ ...style, width }} ref={targetRef}>
        城外的人想进去，城里的人想出来
      </p>
      <Space size="medium">
        <span>文本是否溢出：</span>
        <Radio.Group value={isTextOverflow}>
          <Radio value>是</Radio>
          <Radio value={false}>否</Radio>
        </Radio.Group>
      </Space>
    </Space>
  );
}
